    "remember": "A supply chain is the whole journey from raw material to buyer, and each step depends on the one before.",
    "a": {
      "q": "Which of these describes a supply chain for a cotton T-shirt?",
      "opts": [
        "Growing, spinning, sewing, shipping and selling the shirt",
        "The shop where the shirt is sold to the buyer",
        "The farm where the cotton is grown for the shirt",
        "The ship that carries the finished shirt overseas"
      ],
      "why": "A supply chain covers every step from raw material to buyer. The other options each name only one step, such as the farm or the shop, so they leave out the rest of the journey.",
      "clue": "Look for the option that covers the whole journey."
    },
